-- Source: forever/alliance/40-50/04-tanaris.guide
do
	local function register()
		Polestar.RegisterGuide({
			id = "forever/alliance/40-50/04-tanaris",
			pack = "guides",
			title = "{area:440}",
			faction = "Alliance",
			minLevel = 45,
			maxLevel = 47,
			category = "Leveling",
			zone = 1446,
			zoneName = "Tanaris",
			next = "forever/alliance/40-50/05-the-hinterlands",
			author = "Polestar",
			version = 1,
			names = { ["area:1336"] = "Lost Rigger Cove", ["area:150"] = "Menethil Harbor", ["area:1937"] = "Noonshade Ruins", ["area:1938"] = "Broken Pillar", ["area:2240"] = "Mirage Raceway", ["area:348"] = "Aerie Peak", ["area:35"] = "Booty Bay", ["area:400"] = "Thousand Needles", ["area:439"] = "Shimmering Flats", ["area:440"] = "Tanaris", ["area:47"] = "Hinterlands", ["area:702"] = "Rut'theran Village", ["area:976"] = "Gadgetzan", ["area:977"] = "Steamwheedle Port", ["area:979"] = "Sandsorrow Watch", ["area:981"] = "The Gaping Chasm", ["area:982"] = "The Noxious Lair", ["area:983"] = "Dunemaul Compound", ["area:985"] = "Waterspring Field", ["item:8483"] = "Wastewander Water Pouch", ["item:8584"] = "Untapped Dowsing Widget", ["item:8585"] = "Tapped Dowsing Widget", ["item:8593"] = "Scrimshank's Surveying Gear", ["npc:11758"] = "Andi Lynn", ["npc:12046"] = "Gor'marok the Ravager", ["npc:4196"] = "Silithid Swarm", ["npc:4454"] = "Fizzle Brassbolts", ["npc:4630"] = "Pozzik", ["npc:4709"] = "Zamek", ["npc:5457"] = "Centipaar Swarmer", ["npc:5474"] = "Dunemaul Brute", ["npc:5490"] = "Gnarled Thistleshrub", ["npc:5594"] = "Alchemist Pestlezugg", ["npc:5615"] = "Wastewander Rogue", ["npc:5634"] = "Rhapsody Shindigger", ["npc:5955"] = "Tooga", ["npc:6015"] = "Torta", ["npc:7407"] = "Chief Engineer Bilgewhizzle", ["npc:7408"] = "Spigot Operator Luglunket", ["npc:7583"] = "Sprinkle", ["npc:7763"] = "Curgle Cranklehop", ["npc:7771"] = "Marvon Rivetseeker", ["npc:7847"] = "Caliph Scorpidsting", ["npc:7881"] = "Stoley", ["npc:7882"] = "Security Chief Bilgewhizzle", ["npc:7883"] = "Andre Firebeard", ["object:20805"] = "Rizzle's Unguarded Plans", ["quest:1452"] = "Rhapsody's Kalimdor Kocktail", ["quest:2641"] = "Sprinkle's Secret Ingredient", ["quest:2864"] = "Tran'rek", ["quest:2873"] = "Stoley's Shipment", ["quest:3161"] = "Gahz'ridian", ["quest:3362"] = "Thistleshrub Valley", ["zone:1457"] = "Darnassus" },
			written = { ["Follow the coast south to the pirate cove. Southsea pirates crowd the beach and the boats: work along the edge and pull one at a time. {npc:7883} stands on the far side; {npc:7881}'s stolen cargo lies in the camp.\nCareful: Two or three pirates stand with {npc:7883}, and many more pirates from the town join the fight once it starts."] = "Follow the coast south to the pirate cove. Southsea pirates crowd the beach and the boats: work along the edge and pull one at a time. Andre Firebeard stands on the far side; Stoley's stolen cargo lies in the camp.\nCareful: Two or three pirates stand with Andre, and many more pirates from the town join the fight once it starts.", ["Ride south past the {area:1938} to the {area:981}, the Hazzali tunnels; Scrimshank's gear lies deep inside.\nCareful: One bug guards the gear. Many bugs patrol the tunnels, some of them level 50, so fights often pull extra adds."] = "Ride south past the Broken Pillar to the Gaping Chasm, the Hazzali tunnels; Scrimshank's gear lies deep inside.\nCareful: One bug guards the gear. Many bugs patrol the tunnels, some of them level 50, so fights often pull extra adds.", ["Ride south to the dig camp at the {area:1938}. {npc:7771} hands you a detector helm: wear it to see the {quest:3161} mounds, which lie thick in the sand around the camp and south-west toward the ogres."] = "Ride south to the dig camp at the Broken Pillar. Marvon hands you a detector helm: wear it to see the Gahz'ridian mounds, which lie thick in the sand around the camp and south-west toward the ogres.", ["Ride south-east to {area:985}. {npc:7847} stands in the middle of the southern Wastewander camp: clear around him first.\nCareful: Two stealthed Wastewander Rogues travel with him wherever he goes. At his spawn camp, two shadowmages and their minions are close enough to join a fight with him. Out by the towers you can fight him without them."] = "Ride south-east to Waterspring Field. Caliph stands in the middle of the southern Wastewander camp: clear around him first.\nCareful: Two stealthed Wastewander Rogues travel with him wherever he goes. At his spawn camp, two shadowmages and their minions are close enough to join a fight with him. Out by the towers you can fight him without them.", ["The same poster: {npc:7847} comes much later, after {area:976}"] = "The same poster: Caliph comes much later, after Gadgetzan", ["{area:47}"] = "The Hinterlands" },
