			written = { ["/sit by {npc:265811}'s campfire until you get {spell:1229451}"] = "/sit by Lyreena's campfire until you get Boosted Rest", ["Fel Cones lie under the trees all around {area:186} and {npc:2150}: pick them up on the road east and hand them to {npc:2150} on the way to {npc:7234}."] = "Fel Cones lie under the trees all around Dolanaar and Zenn: pick them up on the road east and hand them to Zenn on the way to Ferocitas.", ["Fly back to {area:702} from {npc:3841}, hand {item:16263} to {npc:10118} on the dock, then fly back to {area:442} for the boat."] = "Fly back to Rut'theran Village from Caylais Moonfeather, hand Laird's Response to Nessa on the dock, then fly back to Auberdine for the boat.", ["Fly to {area:702} once more and take the portal up to {npc:4217}, then fly back to {area:442} for the boat."] = "Fly to Rut'theran Village once more and take the portal up to Mathrengyl, then fly back to Auberdine for the boat.", ["Follow the road south-west out of {area:188}. {npc:2150} sits beside it just east of {area:186}."] = "Follow the road south-west out of Shadowglen. Zenn sits beside it just east of Dolanaar.", ["Gnarlpine Mystics and {npc:7234} camp north-east of {area:260}. {npc:7234} drops the {item:8049}: open it for the jewel.\nCareful: {npc:7234} waits near the camp fire with mystics around him, so pulling him without adds is hard."] = "Gnarlpine Mystics and Ferocitas camp north-east of Starbreeze Village. Ferocitas drops the Gnarlpine Necklace: open it for the jewel.\nCareful: Ferocitas waits near the camp fire with mystics around him, so pulling him without adds is hard.", ["North from the lake to {npc:2150}, on the road back to {area:186}."] = "North from the lake to Zenn, on the road back to Dolanaar.", ["South-west of Starbreeze, south of {npc:2150}. {npc:2080} tends his saplings on the shore; Lasher Sproutlings and Timberlings wander around him, and the {quest:919} grow among them."] = "South-west of Starbreeze, south of Zenn. Denalan tends his saplings on the shore; Lasher Sproutlings and Timberlings wander around him, and the Timberling Sprouts grow among them.", ["Take the portal down to {area:702}. {npc:10118} stands on the dock, {npc:3838} by the hippogryphs. Once you have {quest:6342}, talk to {npc:3838} again and choose the flight to {area:442}: it is free and lands beside {npc:4200}. If the flight map opens instead, close it and talk to him again holding Shift."] = "Take the portal down to Rut'theran Village. Nessa stands on the dock, Vesprystus by the hippogryphs. Once you have Flight to Auberdine, talk to Vesprystus again and choose the flight to Auberdine: it is free and lands beside Laird. If the flight map opens instead, close it and talk to him again holding Shift.", ["{item:8049}, from {npc:7234}"] = "Gnarlpine Necklace, from Ferocitas", ["{npc:10118} stands on the Rut'theran dock where you land. Then take the portal up to {npc:4217} in the {area:1658}."] = "Nessa stands on the Rut'theran dock where you land. Then take the portal up to Mathrengyl in the Cenarion Enclave." },
