			faction = "Alliance",
			classes = { "MAGE" },
			minLevel = 10,
			maxLevel = 15,
			category = "Class",
			folder = "Mage",
			keywords = { "Speak with Jennea", "Mirror Lake", "Jennea Cannon", "Zaldimar Wefhellt", "Jennea's Flask", "Speak with Bink", "Mage-tastic Gizmonitor", "Bink", "Magis Sparkmantle", "Bink's Toolbox", "Speak with Belann", "Boughs in the Wind", "Belann Windwood", "Anathamaas Aetherwind", "Windbough Wand", "Ley Staff", "Ley Orb", "Arcane Staff", "Arcane Orb", "Mage", "class weapon" },
			reward = { { item = 7508, itemName = "Ley Orb", choice = true }, { item = 9513, itemName = "Ley Staff", choice = true }, { item = 7507, itemName = "Arcane Orb", choice = true }, { item = 9514, itemName = "Arcane Staff", choice = true }, { item = 263430, itemName = "Windbough Wand" } },
			why = "A staff or an off-hand orb at 10 from your home town's mage trainer; Skyborne add a wand.",
			zone = 1429,
			zoneName = "Elwynn Forest",
			author = "Polestar",
			version = 1,
			names = { ["area:131"] = "Kharanos", ["area:133"] = "Gnomeregan", ["area:16636"] = "Falaath Village", ["area:16638"] = "Valanaar", ["area:2102"] = "Thunderbrew Distillery", ["area:87"] = "Goldshire", ["item:262668"] = "Wind-Infused Bough", ["item:263430"] = "Windbough Wand", ["item:7207"] = "Jennea's Flask", ["item:7507"] = "Arcane Orb", ["item:7508"] = "Ley Orb", ["item:9513"] = "Ley Staff", ["item:9514"] = "Arcane Staff", ["npc:1211"] = "Leper Gnome", ["npc:1228"] = "Magis Sparkmantle", ["npc:252373"] = "Anathamaas Aetherwind", ["npc:256507"] = "Belann Windwood", ["npc:328"] = "Zaldimar Wefhellt", ["npc:5144"] = "Bink", ["npc:5497"] = "Jennea Cannon", ["object:102984"] = "Bink's Toolbox", ["object:2101"] = "Mage Quarter", ["object:32362"] = "Mystic Ward", ["object:32386"] = "Hall of Mysteries", ["object:697118"] = "Windstone Formation", ["quest:1861"] = "Mirror Lake", ["zone:1453"] = "Stormwind", ["zone:1455"] = "Ironforge", ["zone:2521"] = "Zephras Isle" },
			written = { ["At 10 {npc:1228}, the {area:131} mage trainer in the {area:2102}, sends you to {npc:5144} in {zone:1455}. Taking it shuts out {npc:5497}'s {quest:1861}; you get one staff-or-orb quest. (A Gnome who took {npc:328}'s quest in {area:87} instead follows the {quest:1861} steps; a Human who took this one, the Gizmonitor steps.)"] = "At 10 Magis Sparkmantle, the Kharanos mage trainer in the Thunderbrew Distillery, sends you to Bink in Ironforge. Taking it shuts out Jennea's Mirror Lake; you get one staff-or-orb quest. (A Gnome who took Zaldimar's quest in Goldshire instead follows the Mirror Lake steps; a Human who took this one, the Gizmonitor steps.)", ["Back to {npc:256507}"] = "Back to Belann", ["Back to {npc:5497}"] = "Back to Jennea", ["Follow the road north into {zone:1453} and west to the {object:2101}. {npc:5497} stands at the top of the Wizard's Sanctum, the tall violet tower: climb the spiral ramp and step into the portal near the top, which puts you beside her. She hands you {item:7207}. Skyborne mages take {quest:1861} from her when they first reach {zone:1453}, at about 15."] = "Follow the road north into Stormwind and west to the Mage Quarter. Jennea stands at the top of the Wizard's Sanctum, the tall violet tower: climb the spiral ramp and step into the portal near the top, which puts you beside her. She hands you Jennea's Flask. Skyborne mages take Mirror Lake from her when they first reach Stormwind, at about 15.", ["{npc:256507}'s quest is open to Human and Gnome mages too, if you ever visit {area:16638} on {zone:2521}, the Skyborne home: {npc:252373}, the town's mage trainer, sends you to {npc:256507} next door, who wants a {item:262668} from the ground by the Windstone Formations south of {area:16636}, for the {item:263430}. It does not shut out the staff or the orb."] = "Belann's quest is open to Human and Gnome mages too, if you ever visit Valanaar on Zephras Isle, the Skyborne home: Anathamaas Aetherwind, the town's mage trainer, sends you to Belann Windwood next door, who wants a Wind-Infused Bough from the ground by the Windstone Formations south of Falaath Village, for the Windbough Wand. It does not shut out the staff or the orb.", ["{npc:256507}'s wand (optional)"] = "Belann's wand (optional)" },
			steps = {
				{
					title = "{npc:252373} ({area:16638})",
					note = "At 10 {npc:252373}, the {area:16638} mage trainer, sends you to {npc:256507}, the staff merchant a few steps away in the same town.",
					only = { races = { "Skyborne" } },
					goals = {
						{ t = "level", level = 10 },
