						{ t = "turnin", quest = 93791, title = "Speak with Belann", npc = 256507, npcName = "Belann Windwood", map = 2521, x = 62.91, y = 77.39 },
						{ t = "accept", quest = 93797, title = "Boughs in the Wind", npc = 256507, npcName = "Belann Windwood", minLevel = 10, qlvl = 10, pre = { 93791 }, preTitles = { [93791] = "Speak with Belann" }, map = 2521, x = 62.91, y = 77.39 },
					},
				},
				{
					title = "The Windstone Formations",
					note = "The bough lies on the ground among the Windstone Formations, the wind shrine on the rise west of Fillion's camp, south of {area:16636}. It does not sparkle, so look at the ground by the stones; there are two spots for it.",
