						{ t = "collect", quest = 78092, title = "It Must Be Destroyed", item = 209779, itemName = "Mote of Mannoroth", count = 12, oi = 1, map = 1440, x = 78.48, y = 81.61, f = "e", spotsPacked = "79.3,81.6,,53,23;78,84.1,,40,24;81.1,79.9,,40,3;83,78.5,,43,3;85.3,78,,40,3;87.1,79.3,,40,1;89.1,77.4,,67,5;84.5,74.2,,40,2;84.4,71.3,,40,2;83.1,67.7,,55,5;81,65.8,,48,4;81,70.5,,40,2;82.1,77,,40,1,1;83.2,70.6,,55,5,1;81.6,68.9,,63,5,1", spread = true, lvl = 30, fromNpcs = { { npc = 6071, npcName = "Legion Hound" }, { npc = 6073, npcName = "Searing Infernal" }, { npc = 6115, npcName = "Felguard" }, { npc = 11697, npcName = "Mannoroc Lasher" } } },
					},
				},
				{
					title = "The {object:409311}",
					note = "The {object:409311} stands at the east end of {area:435}. Hand in the motes at the spear with the Althalaxx Orb in your bags: the orb shatters, and the {object:409315} beside it starts the last quest.",
					goals = {
						{ t = "turnin", quest = 78092, title = "It Must Be Destroyed", object = 409311, objName = "Spear of Mannoroth", map = 1440, x = 89.4, y = 77.1, f = "e" },
						{ t = "accept", quest = 78093, title = "Return to Delgren", object = 409315, objName = "Shattered Orb", minLevel = 22, qlvl = 30, map = 1440, x = 89.4, y = 77, f = "e", note = "from the {object:409315}" },
					},
				},
				{
					title = "{quest:78093}",
					note = "Back to {npc:3663} at {area:413} in western {zone:1440}, across the whole zone.",
					goals = {
						{ t = "turnin", quest = 78093, title = "Return to Delgren", npc = 3663, npcName = "Delgren the Purifier", map = 1440, x = 26.2, y = 38.7, z = 4.8, f = "e", note = "{npc:3663}: {item:277205}" },
