			why = "Forever teaches Poisons through this chain, not the trainer; the {item:7676} recipe comes with it.",
			zone = 1453,
			zoneName = "Stormwind City",
			author = "Polestar",
			version = 1,
			names = { ["area:97"] = "Alther's Mill", ["item:2928"] = "Dust of Decay", ["item:3371"] = "Empty Vial", ["item:3372"] = "Leaded Vial", ["item:3421"] = "Simple Wildflowers", ["item:4371"] = "Bronze Tube", ["item:6452"] = "Anti-Venom", ["item:6947"] = "Instant Poison", ["item:7676"] = "Thistle Tea", ["item:7908"] = "Klaven Mortwake's Journal", ["item:7923"] = "Defias Tower Key", ["item:8046"] = "Kearnen's Journal", ["item:8431"] = "Spool of Light Chartreuse Silk Thread", ["item:8432"] = "Eau de Mixilpixil", ["npc:1257"] = "Keldric Boucher", ["npc:1303"] = "Felicia Gump", ["npc:1325"] = "Jasper Fel", ["npc:1326"] = "Sloan McCoy", ["npc:332"] = "Master Mathias Shaw", ["npc:7024"] = "Agent Kearnen", ["npc:7050"] = "Defias Drone", ["npc:7051"] = "Malformed Defias Drone", ["npc:7052"] = "Defias Tower Patroller", ["npc:7053"] = "Klaven Mortwake", ["npc:7207"] = "Doc Mixilpixil", ["object:123214"] = "Duskwood Chest", ["object:2096"] = "Trade District", ["object:2100"] = "Old Town", ["object:2177"] = "The Finest Thread", ["quest:2360"] = "Mathias and the Defias", ["quest:2607"] = "The Touch of Zanzil", ["skill:129"] = "First Aid", ["spell:2983"] = "Sprint", ["spell:526"] = "Cure Poison", ["spell:921"] = "Pick Pocket", ["spell:9810"] = "Touch of Zanzil", ["zone:1431"] = "Duskwood", ["zone:1436"] = "Westfall", ["zone:1453"] = "Stormwind" },
			steps = {
				{
					title = "{quest:2360}",
					note = "At 20 {npc:332}, upstairs in the SI:7 building in {object:2100}, sends you to {npc:7024} in {zone:1436}. This chain is how you learn Poisons on Forever, so do not skip it.",
					goals = {
						{ t = "level", level = 20 },
						{ t = "accept", quest = 2360, title = "Mathias and the Defias", npc = 332, npcName = "Master Mathias Shaw", minLevel = 20, qlvl = 20, map = 1453, x = 78.31, y = 70.74, z = 109.6 },
					},
				},
				{
					title = "{npc:7024}",
					note = "Kearnen hides stealthed against the west side of a big tree with two small trees in front of it, just north of {npc:7053}'s Defias tower in the far east of {zone:1436}, by the {zone:1431} border. Read {item:8046} for the tower's layout if you like.",
					goals = {
						{ t = "turnin", quest = 2360, title = "Mathias and the Defias", npc = 7024, npcName = "Agent Kearnen", map = 1436, x = 68.49, y = 70.08, z = 35.4, f = "e" },
						{ t = "accept", quest = 2359, title = "Klaven's Tower", npc = 7024, npcName = "Agent Kearnen", minLevel = 20, qlvl = 24, pre = { 2360 }, preTitles = { [2360] = "Mathias and the Defias" }, map = 1436, x = 68.49, y = 70.08, z = 35.4, f = "e" },
					},
				},
				{
					title = "The {item:7923}",
					note = "Get the key first. The {npc:7051} (level 23, not elite) starts at the tower entrance and walks a loop around the outside; it is the spiky-haired one trailing yellow sparkles. Stealth up and {spell:921} it from behind: it always has the key. It hits hard: if stealth breaks, {spell:2983} away. Watch for the pair of Defias Drones that also patrol.",
					goals = {
						{ t = "collect", quest = 2359, title = "Klaven's Tower", item = 7923, itemName = "Defias Tower Key", count = 1, oi = 2, map = 1436, x = 69.47, y = 73.99, f = "e", note = "{item:7923}: {spell:921} the {npc:7051}", from = "Malformed Defias Drone", fromKind = "npc", fromId = 7051, fromNpcs = { { npc = 7051, npcName = "Malformed Defias Drone" } } },
					},
				},
				{
					title = "Klaven's journal",
					note = "Sneak up the tower. Defias Tower Patrollers (23) and Sentries (24) guard the floors; an Ambush with a dagger kills them outright if you would rather clear them. {npc:7053}, a level 26 elite, waits on the top floor: Sap him, or bring a friend. The {object:123214} beside his desk needs Lockpicking of about 70-75 (practise on the boxes at {area:97} in Redridge first). A trick: while the Sentries are away, jump from the chair to the lamp to the bookshelf above the chest, step out of stealth and open the chest from there. Opening it poisons you with the {spell:9810}, which stops your stealth for a while and lets the drone see you; that is why the key comes first. Then get out.",
					goals = {
						{ t = "collect", quest = 2359, title = "Klaven's Tower", item = 7908, itemName = "Klaven Mortwake's Journal", count = 1, oi = 1, map = 1436, x = 70.4, y = 74, f = "e", note = "{item:7908}: the {object:123214}, top floor", from = "Duskwood Chest", fromKind = "object", fromId = 123214 },
					},
				},
				{
					title = "{npc:332}",
					note = "Head north through Elwynn to {zone:1453}; Mathias Shaw is upstairs in SI:7. He teaches Poisons and gives you the {item:7676} recipe. Poisons are made, not bought: each batch of {item:6947} takes a {item:2928} and an {item:3371}, which {npc:1325} and {npc:1326} sell in {object:2100} next to SI:7. Buy a stack of each, open Poisons from your spellbook to make them, then use a poison on your weapon.",
					goals = {
						{ t = "turnin", quest = 2359, title = "Klaven's Tower", npc = 332, npcName = "Master Mathias Shaw", map = 1453, x = 78.31, y = 70.74, z = 109.6, note = "{npc:332}: Poisons", rewards = { items = { { item = 18160, itemName = "Recipe: Thistle Tea" } } } },
						{ t = "accept", quest = 2607, title = "The Touch of Zanzil", npc = 332, npcName = "Master Mathias Shaw", minLevel = 20, qlvl = 20, pre = { 2359 }, preTitles = { [2359] = "Klaven's Tower" }, map = 1453, x = 78.31, y = 70.74, z = 109.6 },
					},
				},
				{
					title = "{npc:7207}",
					note = "{quest:2607} still sits on you. {npc:7207} works in the cellar of the SI:7 building: the stairs down are under the stairs to the upper floor, behind {npc:1325}. Target him and type /lay (nothing after it) to be examined, then wait. If he does nothing, abandon the quest, take it again and wait until he asks you to lie down.",
					goals = {
						{ t = "turnin", quest = 2607, title = "The Touch of Zanzil", npc = 7207, npcName = "Doc Mixilpixil", map = 1453, x = 80.06, y = 69.9, z = 95.1 },
						{ t = "accept", quest = 2608, title = "The Touch of Zanzil", npc = 7207, npcName = "Doc Mixilpixil", minLevel = 20, qlvl = 20, pre = { 2607 }, preTitles = { [2607] = "The Touch of Zanzil" }, map = 1453, x = 80.06, y = 69.9, z = 95.1 },
						{ t = "complete", quest = 2608, title = "The Touch of Zanzil", map = 1453, x = 80.06, y = 69.9, note = "/lay with the Doc targeted" },
						{ t = "turnin", quest = 2608, title = "The Touch of Zanzil", npc = 7207, npcName = "Doc Mixilpixil", map = 1453, x = 80.06, y = 69.9, z = 95.1 },
						{ t = "accept", quest = 2609, title = "The Touch of Zanzil", npc = 7207, npcName = "Doc Mixilpixil", minLevel = 20, qlvl = 20, pre = { 2608 }, preTitles = { [2608] = "The Touch of Zanzil" }, map = 1453, x = 80.06, y = 69.9, z = 95.1 },
					},
				},
