					},
				},
				{
					title = "{npc:6176}",
					note = "{npc:6176} camps in the ruins in the east of {zone:1416}: from {area:272} follow the river east of town north into the hills. Pick your weapon: {item:280607}, {item:280605} or {item:280604}.",
					goals = {
						{ t = "turnin", quest = 96016, title = "The Tempest's Weapons", npc = 6176, npcName = "Bath'rah the Windwatcher", map = 1416, x = 80.5, y = 66.92, z = 55.4, f = "e", spotsPacked = "79.83,64.72,,46,1", note = "{npc:6176}: the {item:280696} and your weapon", rewards = { choices = { { item = 280607, itemName = "Lightning's Grasp" }, { item = 280605, itemName = "Tidebringer's Claw" }, { item = 280604, itemName = "Rage of the Storm" } }, items = { { item = 280696, itemName = "Elementalist's Guard" } } } },
