						{ t = "accept", quest = 94467, title = "Call of Fire", npc = 257808, npcName = "Braldir Ashmantle", minLevel = 10, qlvl = 14, pre = { 94466 }, preTitles = { [94466] = "Call of Fire" }, map = 1432, x = 32.17, y = 65.97, f = "e" },
