			zone = 1429,
			zoneName = "Elwynn Forest",
			author = "Polestar",
			version = 1,
			names = { ["area:132"] = "Coldridge Valley", ["area:24"] = "Northshire Abbey", ["area:77"] = "Anvilmar", ["item:6753"] = "Feather Charm", ["item:6785"] = "Powers of the Void", ["item:9576"] = "Tainted Letter", ["item:9577"] = "Tainted Memorandum", ["npc:197"] = "Marshal McBride", ["npc:38"] = "Defias Thug", ["npc:459"] = "Drusilla La Salle", ["npc:460"] = "Alamar Grimm", ["npc:658"] = "Sten Stoutarm", ["npc:946"] = "Frostmane Novice", ["object:83763"] = "Stolen Books", ["spell:688"] = "Summon Imp" },
			written = { ["{npc:459} teaches you {spell:688} at the hand-in: summon it right away, it costs nothing and fights beside you."] = "Drusilla teaches you Summon Imp at the hand-in: summon it right away, it costs nothing and fights beside you.", ["{npc:460} teaches you {spell:688} at the hand-in: summon it right away, it costs nothing and fights beside you."] = "Alamar teaches you Summon Imp at the hand-in: summon it right away, it costs nothing and fights beside you." },
