					title = "{npc:459} (Humans)",
					note = "Your first letter ({item:9576}, from {npc:197} after Kobold Camp Cleanup) points you to {npc:459}, the warlock trainer in the little graveyard beside {area:24}. She asks for a book the Defias stole.",
					only = { races = { "Human" } },
					goals = {
						{ t = "accept", quest = 1598, title = "The Stolen Tome", npc = 459, npcName = "Drusilla La Salle", minLevel = 1, qlvl = 4, closedBy = { 1599 }, preTitles = { [1599] = "Beginnings" }, map = 1429, x = 49.87, y = 42.65, z = 80.8, f = "e" },
					},
				},
				{
					title = "The {object:83763}",
					note = "The Defias tent stands in the vineyard east of the Abbey. The book is small: it lies on the ground just right of the tent's opening, beside a blue jug. Three Defias Thugs (level 3-4) guard the tent; pull them one at a time, or step inside the tent and click the book, where they cannot reach you. The book respawns three minutes after someone takes it.",
					only = { races = { "Human" } },
					goals = {
						{ t = "collect", quest = 1598, title = "The Stolen Tome", item = 6785, itemName = "Powers of the Void", count = 1, oi = 1, map = 1429, x = 56.71, y = 43.96, f = "e", note = "{item:6785}, from the {object:83763}", from = "Stolen Books", fromKind = "object", fromId = 83763 },
					},
				},
				{
					title = "{spell:688}",
					note = "{npc:459} teaches you {spell:688} at the hand-in: summon it right away, it costs nothing and fights beside you.",
					only = { races = { "Human" } },
					goals = {
						{ t = "turnin", quest = 1598, title = "The Stolen Tome", npc = 459, npcName = "Drusilla La Salle", map = 1429, x = 49.87, y = 42.65, z = 80.8, f = "e", note = "{npc:459}: {spell:688}" },
					},
				},
				{
					title = "{npc:460} (Gnomes)",
					note = "Your first letter ({item:9577}, from {npc:658} after Dwarven Outfitters) points you to {npc:460}, the warlock trainer upstairs inside {area:77}. He asks for three Feather Charms.",
					only = { races = { "Gnome" } },
					goals = {
						{ t = "accept", quest = 1599, title = "Beginnings", npc = 460, npcName = "Alamar Grimm", minLevel = 1, qlvl = 4, closedBy = { 1598 }, preTitles = { [1598] = "The Stolen Tome" }, map = 1426, x = 28.65, y = 66.14, z = 399, f = "e" },
					},
				},
				{
					title = "Feather Charms",
					note = "The Frostmane Novices (level 3-4) sit at the back of the troll cave south of {area:77}, near Grek'nir the Cold by the icy pool: take the left tunnel past the entrance. Four kills in five drop a charm, but only two or three novices spawn, so you may wait out their three-minute respawn. They throw frostbolts from range; the Troll Whelps at the cave mouth jump anyone who passes. With the charms, your hearthstone takes you straight back: a new character's is set to {area:132}.",
					only = { races = { "Gnome" } },
					goals = {
						{ t = "collect", quest = 1599, title = "Beginnings", item = 6753, itemName = "Feather Charm", count = 3, oi = 1, map = 1426, x = 30.48, y = 79.54, f = "e", spotsPacked = "30.4,80.2,,23,3;29.2,82.1,,46,5", lvl = 4, note = "Feather Charms", from = "Frostmane Novice", fromKind = "npc", fromId = 946, fromNpcs = { { npc = 946, npcName = "Frostmane Novice" } } },
					},
				},
				{
					title = "{spell:688}",
					note = "{npc:460} teaches you {spell:688} at the hand-in: summon it right away, it costs nothing and fights beside you.",
					only = { races = { "Gnome" } },
					goals = {
						{ t = "turnin", quest = 1599, title = "Beginnings", npc = 460, npcName = "Alamar Grimm", map = 1426, x = 28.65, y = 66.14, z = 399, f = "e", note = "{npc:460}: {spell:688}" },
					},
				},
			},
		})
	end
	register()
end

