do
	local function register()
		Polestar.RegisterGuide({
			id = "forever/class/warlock/incubus-alliance",
			pack = "guides",
			title = "Succubus and Incubus (Alliance)",
			faction = "Alliance",
			classes = { "WARLOCK" },
			minLevel = 20,
			maxLevel = 25,
			category = "Class",
			folder = "Warlock",
			keywords = { "Summon Succubus", "Summon Incubus", "sayaad", "Gakin's Summons", "Devourer of Souls", "Heartswood", "Heartswood Core", "What Is Love?", "Unlit Torch", "Burning Torch", "Wooden Figurine", "Ordil'Aran", "Maestra's Post", "Lago Blackwrench", "Gakin the Darkbinder", "Takar the Seer", "The Binding", "Small Soul Pouch", "Warlock", "class pet" },
			reward = { { spell = 712, spellName = "Summon Succubus" }, { spell = 713, spellName = "Summon Incubus" }, { item = 22243, itemName = "Small Soul Pouch" } },
			why = "At 20: the succubus and Forever's incubus, its male twin, each with a soul pouch for your shards.",
			zone = 1453,
			zoneName = "Stormwind City",
			author = "Polestar",
			version = 1,
			names = { ["area:150"] = "Menethil Harbor", ["area:2257"] = "Deeprun Tram", ["area:35"] = "Booty Bay", ["area:378"] = "Camp Taurajo", ["area:392"] = "Ratchet", ["area:413"] = "Maestra's Post", ["area:414"] = "Zoram Strand", ["area:415"] = "Astranaar", ["item:190307"] = "Unlit Torch", ["item:190308"] = "Burning Torch", ["item:190309"] = "Wooden Figurine", ["item:6898"] = "Orb of Soran'ruk", ["item:6913"] = "Heartswood Core", ["npc:185335"] = "Summoned Incubus", ["npc:6120"] = "Lago Blackwrench", ["npc:6122"] = "Gakin the Darkbinder", ["npc:6244"] = "Takar the Seer", ["npc:6247"] = "Doan Karhan", ["object:2101"] = "Mage Quarter", ["object:2164"] = "Slaughtered Lamb", ["object:29784"] = "Basic Campfire", ["object:32383"] = "Forlorn Cavern", ["quest:1716"] = "Devourer of Souls", ["quest:1717"] = "Gakin's Summons", ["quest:1738"] = "Heartswood", ["quest:1739"] = "The Binding", ["quest:65603"] = "The Binding", ["spell:712"] = "Summon Succubus", ["spell:713"] = "Summon Incubus", ["zone:1413"] = "Barrens", ["zone:1439"] = "Darkshore", ["zone:1440"] = "Ashenvale", ["zone:1445"] = "Dustwallow Marsh", ["zone:1453"] = "Stormwind", ["zone:1455"] = "Ironforge" },
			written = { ["Back to {npc:6122} with the {quest:1738}. He hands you the {item:6913}: take the stairs behind him down to the crypt; part way along the lowest corridor a side stair on the left leads to the room with the purple circle. Stand on it and use the core. Summon your voidwalker first and keep the succubus (level 20, not elite) on the circle, or the guards may kill her and the kill does not count. If she wins, use the core again; keep it, {npc:6122} takes it back."] = "Back to Gakin with the Heartswood. He hands you the Heartswood Core: take the stairs behind him down to the crypt; part way along the lowest corridor a side stair on the left leads to the room with the purple circle. Stand on it and use the core. Summon your voidwalker first and keep the succubus (level 20, not elite) on the circle, or the guards may kill her and the kill does not count. If she wins, use the core again; keep it, Gakin takes it back.", ["Give Gakin the figurine, then use the {item:190309} at the middle of the same circle and defeat the incubus it calls (level 20, not elite; it can charm you) with your voidwalker tanking. Keep the figurine: {npc:6122} takes it back."] = "Give Gakin the figurine, then use the Wooden Figurine at the middle of the same circle and defeat the incubus it calls (level 20, not elite; it can charm you) with your voidwalker tanking. Keep the figurine: Gakin takes it back.", ["Ordil'Aran lies in north-west {zone:1440}, north of {area:415} along the road toward {zone:1439}. About twenty Dark Strand cultists hold the ruins around the great tree: keep to the outer wall, and click the {quest:1738} from as far away as it lets you. It is turned in to {npc:6122}, not to Takar."] = "Ordil'Aran lies in north-west Ashenvale, north of Astranaar along the road toward Darkshore. About twenty Dark Strand cultists hold the ruins around the great tree: keep to the outer wall, and click the Heartswood from as far away as it lets you. It is turned in to Gakin, not to Takar." },
			steps = {
				{
					title = "{quest:1717} (Gnomes)",
					note = "At 20 {npc:6120}, the warlock trainer in {zone:1455}'s {object:32383}, sends you to {npc:6122} in {zone:1453}. Take the {area:2257}.",
					only = { races = { "Gnome" } },
					goals = {
						{ t = "level", level = 20 },
						{ t = "accept", quest = 1717, title = "Gakin's Summons", npc = 6120, npcName = "Lago Blackwrench", minLevel = 20, qlvl = 20, closedBy = { 1716 }, preTitles = { [1716] = "Devourer of Souls" }, map = 1455, x = 47.63, y = 9.26, z = 501.5, f = "e" },
					},
				},
				{
					title = "{quest:1716}",
					note = "At 20 {npc:6122}, in the cellar of the {object:2164} in the {object:2101}, sends you to {npc:6244} in the {zone:1413}: a long trip for the Alliance. Take the boat from {area:150} to Theramore and head west through {zone:1445}, or the boat from {area:35} to {area:392}.",
					goals = {
						{ t = "level", level = 20 },
						{ t = "turnin", quest = 1717, title = "Gakin's Summons", npc = 6122, npcName = "Gakin the Darkbinder", map = 1453, x = 39.22, y = 85.23, z = 101.5, only = { races = { "Gnome" } } },
						{ t = "accept", quest = 1716, title = "Devourer of Souls", npc = 6122, npcName = "Gakin the Darkbinder", minLevel = 20, map = 1453, x = 39.22, y = 85.23, z = 101.5 },
					},
				},
				{
					title = "{npc:6244}",
					note = "{npc:6244} camps at a tent with a campfire just north-east of {area:378}, by a fork in the road: Horde ground, so come in from the east and keep clear of the Taurajo guards. {npc:6247} beside him starts the {item:6898}. Takar offers both branches: take both.",
					goals = {
						{ t = "turnin", quest = 1716, title = "Devourer of Souls", npc = 6244, npcName = "Takar the Seer", map = 1413, x = 49.31, y = 57.1, z = 91.8, f = "e" },
						{ t = "accept", quest = 1738, title = "Heartswood", npc = 6244, npcName = "Takar the Seer", minLevel = 20, qlvl = 20, pre = { 1716 }, preTitles = { [1716] = "Devourer of Souls" }, map = 1413, x = 49.31, y = 57.1, z = 91.8, f = "e", note = "the succubus" },
						{ t = "accept", quest = 65602, title = "What Is Love?", npc = 6244, npcName = "Takar the Seer", minLevel = 20, qlvl = 20, pre = { 1716 }, preTitles = { [1716] = "Devourer of Souls" }, map = 1413, x = 49.31, y = 57.1, z = 91.8, f = "e", note = "the incubus" },
					},
				},
				{
					title = "{quest:1738}",
					note = "Ordil'Aran lies in north-west {zone:1440}, north of {area:415} along the road toward {zone:1439}. About twenty Dark Strand cultists hold the ruins around the great tree: keep to the outer wall, and click the {quest:1738} from as far away as it lets you. It is turned in to {npc:6122}, not to Takar.",
					goals = {
						{ t = "collect", quest = 1738, title = "Heartswood", item = 6912, itemName = "Heartswood", count = 1, oi = 1, map = 1440, x = 31.55, y = 31.57, f = "e", from = "Heartswood", fromKind = "object", fromId = 93192 },
					},
				},
				{
					title = "The {item:190309}",
					note = "The house stands alone in the trees of north-western {zone:1440}, north-west of Ordil'Aran and well north of {area:413}: do it on the same trip as the {quest:1738}. Take the {item:190307} from the table outside, light it at a campfire (a {object:29784} of your own, or Talen's fire on {area:414}), and go straight back: the {item:190308} burns out after five minutes, so a fire of your own beside the house is quickest. Without it the figure in the house stops you. The figurine is upstairs.",
					goals = {
						{ t = "collect", item = 190307, itemName = "Unlit Torch", map = 1440, x = 26.79, y = 22.43, f = "e", optional = true, note = "{item:190307}, on the table outside", from = "Unlit Torch", fromKind = "object", fromId = 400001 },
						{ t = "collect", quest = 65602, title = "What Is Love?", item = 190309, itemName = "Wooden Figurine", count = 1, oi = 1, map = 1440, x = 26.61, y = 22.03, f = "e", note = "{item:190309}, upstairs", from = "Wooden Figurine", fromKind = "object", fromId = 375544 },
					},
				},
				{
					title = "{quest:1739}: succubus",
					note = "Back to {npc:6122} with the {quest:1738}. He hands you the {item:6913}: take the stairs behind him down to the crypt; part way along the lowest corridor a side stair on the left leads to the room with the purple circle. Stand on it and use the core. Summon your voidwalker first and keep the succubus (level 20, not elite) on the circle, or the guards may kill her and the kill does not count. If she wins, use the core again; keep it, {npc:6122} takes it back.",
					goals = {
						{ t = "turnin", quest = 1738, title = "Heartswood", npc = 6122, npcName = "Gakin the Darkbinder", map = 1453, x = 39.22, y = 85.23, z = 101.5 },
						{ t = "accept", quest = 1739, title = "The Binding", npc = 6122, npcName = "Gakin the Darkbinder", minLevel = 20, qlvl = 20, pre = { 1738 }, preTitles = { [1738] = "Heartswood" }, map = 1453, x = 39.22, y = 85.23, z = 101.5 },
						{ t = "use", item = 6913, itemName = "Heartswood Core", map = 1453, x = 39.1, y = 84.4, note = "{item:6913}, on the circle in the crypt" },
						{ t = "kill", quest = 1739, title = "The Binding", target = "Summoned Succubus", npc = 5677, count = 1, oi = 1, map = 1453, x = 25.1, y = 77.4, f = "e" },
						{ t = "turnin", quest = 1739, title = "The Binding", npc = 6122, npcName = "Gakin the Darkbinder", map = 1453, x = 39.22, y = 85.23, z = 101.5, note = "{npc:6122}: {spell:712}" },
					},
				},
				{
					title = "{quest:65603}: incubus",
					note = "Give Gakin the figurine, then use the {item:190309} at the middle of the same circle and defeat the incubus it calls (level 20, not elite; it can charm you) with your voidwalker tanking. Keep the figurine: {npc:6122} takes it back.",
					goals = {
						{ t = "turnin", quest = 65602, title = "What Is Love?", npc = 6122, npcName = "Gakin the Darkbinder", map = 1453, x = 39.22, y = 85.23, z = 101.5 },
						{ t = "accept", quest = 65603, title = "The Binding", npc = 6122, npcName = "Gakin the Darkbinder", minLevel = 20, qlvl = 20, pre = { 65602 }, preTitles = { [65602] = "What Is Love?" }, map = 1453, x = 39.22, y = 85.23, z = 101.5 },
						{ t = "kill", quest = 65603, title = "The Binding", target = "Summoned Incubus", npc = 185335, oi = 1, map = 1453, x = 39.35, y = 84.74, spotsPacked = "39,84.7,,15,3", lvl = 20, note = "{npc:185335}, at the circle in the crypt" },
						{ t = "turnin", quest = 65603, title = "The Binding", npc = 6122, npcName = "Gakin the Darkbinder", map = 1453, x = 39.22, y = 85.23, z = 101.5, note = "{npc:6122}: {spell:713}" },
					},
				},
			},
		})
	end
	register()
end

