						{ t = "use", item = 6928, itemName = "Bloodstone Choker", map = 1453, x = 39.1, y = 84.4, note = "{item:6928}, on the circle in the crypt" },
						{ t = "kill", quest = 1689, title = "The Binding", target = "Summoned Voidwalker", npc = 5676, count = 1, oi = 1, map = 1453, x = 25.1, y = 77.4, f = "e" },
						{ t = "turnin", quest = 1689, title = "The Binding", npc = 6122, npcName = "Gakin the Darkbinder", map = 1453, x = 39.22, y = 85.23, z = 101.5, note = "{npc:6122}: {spell:697}" },
					},
